    // REMOVED entries are compatibility symbols for dormant imported source; never registered.
    public enum Kind { BOSS, PET, MOB, PASSIVE, HELPER, REMOVED }
    public final String title,id;
    public final Kind kind;
    public final double health,damage,armor,speed;
    public final float width,height,scale,lift;
    public final int style;
    public final boolean aquatic,ranged;
    Species(String title,Kind kind,double health,double damage,double armor,double speed,float width,float height,float scale,float lift,int style,boolean aquatic,boolean ranged){
        this.title=title;this.id=name().toLowerCase(java.util.Locale.ROOT);this.kind=kind;
        this.health=health;this.damage=damage;this.armor=armor;this.speed=speed;this.width=width;this.height=height;this.scale=scale;this.lift=lift;this.style=style;this.aquatic=aquatic;this.ranged=ranged;
    }
    public boolean boss(){return kind==Kind.BOSS;}
    public String breathElement(){
        if(this==EMBER_DRAKE)return "fire";
        if(this==TIDE_DRAKE)return "water";
        if(this==DAWN_LIGHTNING_DRAGON)return "lightning";
        if(this==DAWN_ICE_DRAGON)return "frost";
        if(id.contains("electrica")||id.contains("electrode"))return "lightning";
        if(id.contains("frostlok"))return "frost";
        if(id.contains("fire"))return "fire";
        if(id.contains("water"))return "water";
        if(id.contains("earth"))return "earth";
        if(id.contains("wind"))return "wind";
        return "spirit";
    }
    public boolean passive(){return kind==Kind.PASSIVE;}
    public boolean dragon(){return this==EMBER_DRAKE||this==TIDE_DRAKE||this==DUSK_DRAKE||this==DAWN_FIRE_DRAGON||this==DAWN_ICE_DRAGON||this==DAWN_LIGHTNING_DRAGON;}
    private static final java.util.List<Species> BOSSES=java.util.List.of(
        DAWN_CORRUPTED_OGRE,
        MOBOSSES_NIL,
        MOBOSSES_ROYAL_GUARDIAN,
        DAWN_MARTIAN,
        DAWN_SKELETONLORD,
        DAWN_DRAGON_LORD,
        MOBOSSES_DEMON_KING,
        MOBOSSES_HEROBRINE,
        DAWN_NOTCH_BOSS,
        DAWN_HEROBRINE
    );
    public static final int BOSS_COUNT=BOSSES.size();
    public int bossStage(){return BOSSES.indexOf(this);}
    public static Species boss(int stage){return BOSSES.get(stage);}
